-- Encrypted immutable PDF archives for finalized reports and receipts.
alter table public.drive_cleanup_queue drop constraint drive_cleanup_queue_source_type_check;
alter table public.drive_cleanup_queue add constraint drive_cleanup_queue_source_type_check check(source_type in('application_document','staff_document','center_logo','license_evidence','pdf_archive'));
create table public.archived_pdf_documents(id uuid primary key default gen_random_uuid(),center_id uuid not null references public.centers(id),entity_type text not null check(entity_type in('monthly_report','receipt')),entity_id uuid not null,drive_file_id text not null unique,encrypted_file_name text not null check(encrypted_file_name~'^enc_[a-f0-9]{24}\.bin$'),file_hash text not null check(file_hash~'^[a-f0-9]{64}$'),plain_size integer not null check(plain_size between 1 and 10485760),encrypted_size integer not null check(encrypted_size>plain_size and encrypted_size<=10485824),drive_path_key text not null,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),unique(entity_type,entity_id,file_hash));create index archived_pdf_center_idx on public.archived_pdf_documents(center_id,entity_type,created_at desc);alter table public.archived_pdf_documents enable row level security;alter table public.archived_pdf_documents force row level security;create policy archived_pdf_tenant_read on public.archived_pdf_documents for select to authenticated using(private.is_center_manager(center_id)or(center_id=private.current_center_id()and private.current_role()='operator'and private.mfa_satisfied()));revoke all on public.archived_pdf_documents from anon,authenticated;grant select on public.archived_pdf_documents to authenticated;create trigger archived_pdf_immutable before update or delete on public.archived_pdf_documents for each row execute function private.prevent_receipt_mutation();
create or replace function public.register_archived_pdf(p_entity_type text,p_entity_id uuid,p_drive_file_id text,p_encrypted_file_name text,p_file_hash text,p_plain_size integer,p_encrypted_size integer,p_drive_path_key text)returns uuid language plpgsql security definer set search_path=pg_catalog,public,private as $$declare cid uuid;rid uuid;begin
 if not private.mfa_satisfied()or private.current_role()not in('owner','operator')then raise exception'Operational authentication required';end if;cid:=private.current_center_id();if p_entity_type='monthly_report'then if private.current_role()<>'owner'or not exists(select 1 from public.monthly_government_reports r where r.id=p_entity_id and r.center_id=cid)then raise exception'Report not found';end if;elsif p_entity_type='receipt'then if private.current_role()<>'operator'or not private.operator_has_permission('receipt.print')or not exists(select 1 from public.receipts r where r.id=p_entity_id and r.center_id=cid)then raise exception'Receipt not found';end if;else raise exception'Invalid archive type';end if;
 if char_length(p_drive_file_id)not between 10 and 255 or p_encrypted_file_name!~'^enc_[a-f0-9]{24}\.bin$'or p_file_hash!~'^[a-f0-9]{64}$'or p_plain_size not between 1 and 10485760 or p_encrypted_size<=p_plain_size or p_encrypted_size>10485824 or char_length(p_drive_path_key)not between 10 and 500 then raise exception'Invalid PDF archive metadata';end if;insert into public.archived_pdf_documents(center_id,entity_type,entity_id,drive_file_id,encrypted_file_name,file_hash,plain_size,encrypted_size,drive_path_key,created_by)values(cid,p_entity_type,p_entity_id,p_drive_file_id,p_encrypted_file_name,p_file_hash,p_plain_size,p_encrypted_size,p_drive_path_key,auth.uid())returning id into rid;perform private.write_audit_log(cid,'pdf.archive_registered','archived_pdf',rid,jsonb_build_object('entity_type',p_entity_type,'entity_id',p_entity_id,'file_hash',p_file_hash));return rid;
end;$$;revoke execute on function public.register_archived_pdf(text,uuid,text,text,text,integer,integer,text)from public,anon;grant execute on function public.register_archived_pdf(text,uuid,text,text,text,integer,integer,text)to authenticated;comment on table public.archived_pdf_documents is'Immutable metadata for user-exported finalized PDFs encrypted into Center/Year/Month/Archives Drive folders.';
